syntax:
C++ syntax demonstrating potential for RVO and NRVO:

```cpp
class ExpensiveObject {
public:
  ExpensiveObject() { std::cout << "Constructor called\n"; }
  ExpensiveObject(const ExpensiveObject& other) { std::cout << "Copy constructor called\n"; }
  ExpensiveObject(ExpensiveObject&& other) { std::cout << "Move constructor called\n"; }
  ~ExpensiveObject() { std::cout << "Destructor called\n"; }
};

ExpensiveObject createExpensiveObject() {
  ExpensiveObject obj;
  return obj; // RVO likely
}

ExpensiveObject createExpensiveObjectNamed() {
  ExpensiveObject obj;
  return obj; // NRVO likely
}

ExpensiveObject createExpensiveObjectCopy() {
  ExpensiveObject obj;
  ExpensiveObject copy = obj; // Copy required even with RVO
  return copy; 
}
```

